}

contracts/CreditScoreSBT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721URIStorage.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";

/**
 * @title CreditScoreSBT
 * @dev Soulbound Token (SBT) implementing ERC-5192 -- non-transferable.
 *      Represents a user's on-chain credit/reputation score from marketplace activity.
 *
 * Tier System:
 *   0-99    => BRONZE  (default, just registered)
 *   100-299 => SILVER  (can access installment payments / reduced fees)
 *   300-599 => GOLD    (priority listing, max fee discounts)
 *   600+    => DIAMOND (VIP -- top tier privileges)
 *
 * Score Calculation (off-chain by backend AI module, committed on-chain):
 *   +15 per completed order (no dispute)
 *   +5  per on-time payment (< 1hr after placement)
 *   -30 per dispute raised against user
 *   -50 per fraud detection flag
 *   +3  per 5-star review given
 *
 * Credit privileges (enforced in EscrowCore):
 *   SILVER: platform fee 2.0% (default 2.5%)
 *   GOLD:   platform fee 1.5%, can buy on installment
 *   DIAMOND: platform fee 1.0%, priority seller queue, undercollateralized loans (future)
 */
contract CreditScoreSBT is ERC721, ERC721URIStorage, AccessControl {

    // ERC-5192: Minimal Soulbound Token interface
    bytes4 private constant ERC5192_INTERFACE_ID = 0xb45a3c0e;
    event Locked(uint256 tokenId);
    event Unlocked(uint256 tokenId); // SBT: emitted only for admin forced unlock

    bytes32 public constant UPDATER_ROLE = keccak256("UPDATER_ROLE");
    bytes32 public constant ADMIN_ROLE   = keccak256("ADMIN_ROLE");

    uint256 private _nextTokenId;

    enum Tier { BRONZE, SILVER, GOLD, DIAMOND }

    struct ScoreRecord {
        int256 score;           // Can go negative (fraud penalty)
        uint256 completedOrders;
        uint256 disputes;
        uint256 fraudFlags;
        uint256 lastUpdated;
        Tier tier;
    }

    // wallet - tokenId
    mapping(address => uint256) public walletToToken;

    // tokenId - score data
    mapping(uint256 => ScoreRecord) public scoreOf;

    // -- Tier thresholds --
    int256 public constant SILVER_THRESHOLD  = 100;
    int256 public constant GOLD_THRESHOLD    = 300;
    int256 public constant DIAMOND_THRESHOLD = 600;

    // -- Score deltas --
    int256 public constant SCORE_COMPLETED_ORDER = 15;
    int256 public constant SCORE_ONTIME_PAYMENT  = 5;
    int256 public constant SCORE_DISPUTE_PENALTY = -30;
    int256 public constant SCORE_FRAUD_PENALTY   = -50;
    int256 public constant SCORE_5STAR_REVIEW    = 3;

    // -- Platform fee bps per tier (for EscrowCore to query) --
    uint256 public constant FEE_BRONZE  = 250; // 2.5%
    uint256 public constant FEE_SILVER  = 200; // 2.0%
    uint256 public constant FEE_GOLD    = 150; // 1.5%
    uint256 public constant FEE_DIAMOND = 100; // 1.0%

    // -- Events --
    event SBTMinted(address indexed wallet, uint256 tokenId);
    event ScoreUpdated(address indexed wallet, int256 newScore, Tier newTier, string reason);
    event TierUpgraded(address indexed wallet, Tier oldTier, Tier newTier);
    event TierDowngraded(address indexed wallet, Tier oldTier, Tier newTier);

    constructor() ERC721("Web3Market Credit Score", "W3MCREDIT") {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
        _grantRole(UPDATER_ROLE, msg.sender);
    }

    // -----------------------------------------
    // MINT - one SBT per wallet, auto-minted on first interaction
    // -----------------------------------------

    function mintSBT(address wallet) external onlyRole(UPDATER_ROLE) returns (uint256) {
        require(walletToToken[wallet] == 0, "SBT already exists");
        uint256 tokenId = ++_nextTokenId;
        _safeMint(wallet, tokenId);
        walletToToken[wallet] = tokenId;
        scoreOf[tokenId] = ScoreRecord({
            score: 0,
            completedOrders: 0,
            disputes: 0,
            fraudFlags: 0,
            lastUpdated: block.timestamp,
            tier: Tier.BRONZE
        });

        emit SBTMinted(wallet, tokenId);
        emit Locked(tokenId); // ERC-5192: immediately soulbound
        return tokenId;
    }

    // -----------------------------------------
    // SCORE UPDATE -- called by backend after each order completion
    // ---------------------------------------------------------

    /**
     * @dev Record a completed order. Grants +SCORE_COMPLETED_ORDER points.
     *      If payment was on-time, grants extra +SCORE_ONTIME_PAYMENT.
     */
    function recordCompletedOrder(
        address wallet,
        bool onTime,
        string calldata reason
    ) external onlyRole(UPDATER_ROLE) {
        uint256 tokenId = _ensureSBT(wallet);
        ScoreRecord storage rec = scoreOf[tokenId];

        int256 delta = SCORE_COMPLETED_ORDER + (onTime ? SCORE_ONTIME_PAYMENT : int256(0));
        rec.score += delta;
        rec.completedOrders++;
        rec.lastUpdated = block.timestamp;

        _updateTierAndURI(wallet, tokenId, rec, reason);
    }

    /**
     * @dev Record a dispute raised against this wallet. Penalises score.
     */
    function recordDispute(address wallet, string calldata reason) external onlyRole(UPDATER_ROLE) {
        uint256 tokenId = _ensureSBT(wallet);
        ScoreRecord storage rec = scoreOf[tokenId];
        rec.score += SCORE_DISPUTE_PENALTY;
        rec.disputes++;
        rec.lastUpdated = block.timestamp;
        _updateTierAndURI(wallet, tokenId, rec, reason);
    }

    /**
     * @dev Admin flags fraud. Major score penalty.
     */
    function recordFraudFlag(address wallet, string calldata reason) external onlyRole(ADMIN_ROLE) {
        uint256 tokenId = _ensureSBT(wallet);
        ScoreRecord storage rec = scoreOf[tokenId];
        rec.score += SCORE_FRAUD_PENALTY;
        rec.fraudFlags++;
        rec.lastUpdated = block.timestamp;
        _updateTierAndURI(wallet, tokenId, rec, reason);
    }

    /**
     * @dev Backend bulk update with a pre-computed score delta + new IPFS metadata URI.
     *      The backend AI module runs full scoring and calls this with final result.
     */
    function updateScore(
        address wallet,
        int256 scoreDelta,
        string calldata newTokenUri,
        string calldata reason
    ) external onlyRole(UPDATER_ROLE) {
        uint256 tokenId = _ensureSBT(wallet);
        ScoreRecord storage rec = scoreOf[tokenId];
        rec.score += scoreDelta;
        rec.lastUpdated = block.timestamp;
        _setTokenURI(tokenId, newTokenUri);
        _updateTierAndURI(wallet, tokenId, rec, reason);
    }

    // -----------------------------------------
    // INTERNAL HELPERS
    // -----------------------------------------

    function _ensureSBT(address wallet) internal returns (uint256) {
        if (walletToToken[wallet] == 0) {
            return _mintInternal(wallet);
        }
        return walletToToken[wallet];
    }

    function _mintInternal(address wallet) internal returns (uint256) {
        uint256 tokenId = ++_nextTokenId;
        _safeMint(wallet, tokenId);
        walletToToken[wallet] = tokenId;
        scoreOf[tokenId] = ScoreRecord({
            score: 0, completedOrders: 0, disputes: 0, fraudFlags: 0,
            lastUpdated: block.timestamp, tier: Tier.BRONZE
        });
        emit SBTMinted(wallet, tokenId);
        emit Locked(tokenId);
        return tokenId;
    }

    function _updateTierAndURI(
        address wallet,
        uint256 tokenId,
        ScoreRecord storage rec,
        string memory reason
    ) internal {
        Tier newTier = _computeTier(rec.score);
        if (newTier != rec.tier) {
            Tier old = rec.tier;
            rec.tier = newTier;
            if (uint8(newTier) > uint8(old)) emit TierUpgraded(wallet, old, newTier);
            else emit TierDowngraded(wallet, old, newTier);
        }
        emit ScoreUpdated(wallet, rec.score, rec.tier, reason);
    }

    function _computeTier(int256 score) internal pure returns (Tier) {
        if (score >= DIAMOND_THRESHOLD) return Tier.DIAMOND;
        if (score >= GOLD_THRESHOLD)    return Tier.GOLD;
        if (score >= SILVER_THRESHOLD)  return Tier.SILVER;
        return Tier.BRONZE;
    }

    // -----------------------------------------
    // PRIVILEGE QUERIES - used by EscrowCore
    // -----------------------------------------

    function getPlatformFee(address wallet) external view returns (uint256) {
        uint256 tokenId = walletToToken[wallet];
        if (tokenId == 0) return FEE_BRONZE;
        Tier tier = scoreOf[tokenId].tier;
        if (tier == Tier.DIAMOND) return FEE_DIAMOND;
        if (tier == Tier.GOLD)    return FEE_GOLD;
        if (tier == Tier.SILVER)  return FEE_SILVER;
        return FEE_BRONZE;
    }

    function getTier(address wallet) external view returns (Tier) {
        uint256 tokenId = walletToToken[wallet];
        if (tokenId == 0) return Tier.BRONZE;
        return scoreOf[tokenId].tier;
    }

    function getScore(address wallet) external view returns (int256) {
        uint256 tokenId = walletToToken[wallet];
        if (tokenId == 0) return 0;
        return scoreOf[tokenId].score;
    }

    function canInstallment(address wallet) external view returns (bool) {
        uint256 tokenId = walletToToken[wallet];
        if (tokenId == 0) return false;
        return uint8(scoreOf[tokenId].tier) >= uint8(Tier.GOLD);
    }

    function canPriorityList(address wallet) external view returns (bool) {
        uint256 tokenId = walletToToken[wallet];
        if (tokenId == 0) return false;
        return uint8(scoreOf[tokenId].tier) >= uint8(Tier.GOLD);
    }

    // -----------------------------------------
    // SOULBOUND - DISABLE TRANSFERS (ERC-5192)
    // -----------------------------------------

    function locked(uint256 /*tokenId*/) external pure returns (bool) {
        return true; // always locked
    }

    function _update(
        address to,
        uint256 tokenId,
        address auth
    ) internal override returns (address) {
        address from = _ownerOf(tokenId);
        // Allow minting (from == 0) and admin-initiated burn (to == 0), block transfers
        require(
            from == address(0) || to == address(0) || hasRole(ADMIN_ROLE, auth),
            "SBT: non-transferable"
        );
        return super._update(to, tokenId, auth);
    }

    // -----------------------------------------
    // OVERRIDES
    // -----------------------------------------

    function tokenURI(uint256 tokenId)
        public view override(ERC721, ERC721URIStorage) returns (string memory)
    {
        return super.tokenURI(tokenId);
    }

    function supportsInterface(bytes4 interfaceId)
        public view override(ERC721, ERC721URIStorage, AccessControl) returns (bool)
    {
        return interfaceId == ERC5192_INTERFACE_ID || super.supportsInterface(interfaceId);
    }
}

contracts/EscrowCore.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

// Interface for DEX Swap (e.g., Uniswap V2 / PancakeSwap Router)
interface ISwapRouter {
    function swapExactTokensForTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external returns (uint[] memory amounts);
}

/// @dev Minimal interface to CreditScoreSBT for dynamic fee & privilege queries
interface ICreditScoreSBT {
    function getPlatformFee(address wallet) external view returns (uint256);
    function recordCompletedOrder(address wallet, bool onTime, string calldata reason) external;
    function recordDispute(address wallet, string calldata reason) external;
    function getTier(address wallet) external view returns (uint8);
}

/**
 * @title EscrowCore
 * @dev Multi-token escrow contract with:
 *   - Native coin and ERC20 DEX Swap support
 *   - Dynamic platform fee via CreditScoreSBT (Silver/Gold buyers pay less)
 *   - Event-driven credit score updates on delivery confirmation
 *   - buyerConfirmDelivery for trustless release without backend
 */
contract EscrowCore is ReentrancyGuard, AccessControl, Pausable {
    using SafeERC20 for IERC20;

    bytes32 public constant ADMIN_ROLE    = keccak256("ADMIN_ROLE");
    bytes32 public constant OPERATOR_ROLE = keccak256("OPERATOR_ROLE");

    /// @dev Optional - set to zero address to disable SBT features
    ICreditScoreSBT public sbtContract;


    struct Order {
        address buyer;
        address seller;
        address token; // address(0) means native coin (ETH/MATIC/BNB)
        uint256 amount;
        uint256 fee;
        OrderStatus status;
        uint256 createdAt;
        uint256 expiresAt;
    }
    
    enum OrderStatus { 
        Pending, 
        Paid, 
        Completed, 
        Refunded, 
        Disputed,
        Expired
    }
    
    mapping(bytes32 => Order) public orders;
    address public feeVault;
    uint256 public platformFeePercent = 250; // 2.5% default (overridden by SBT tier)
    uint256 public constant MAX_FEE_PERCENT = 1000; // 10%
    uint256 public constant ORDER_TIMEOUT = 30 days;
    
    event OrderCreated(
        bytes32 indexed orderId, 
        address indexed buyer, 
        address indexed seller, 
        address token,
        uint256 amount,
        uint256 fee
    );
    event OrderCompleted(bytes32 indexed orderId);
    event OrderRefunded(bytes32 indexed orderId);
    event OrderDisputed(bytes32 indexed orderId);
    event OrderExpired(bytes32 indexed orderId);
    event FeeUpdated(uint256 newFee);
    event FeeVaultUpdated(address newVault);
    /// @dev Emitted when buyer confirms delivery - backend listens to update CreditScoreSBT
    event DeliveryConfirmed(bytes32 indexed orderId, address indexed buyer, address indexed seller, bool onTime);
    event SBTContractUpdated(address newSBT);

    constructor(address _feeVault) {
        require(_feeVault != address(0), "Invalid fee vault");
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
        _grantRole(OPERATOR_ROLE, msg.sender);
        feeVault = _feeVault;
    }

    /// @dev Connect the CreditScoreSBT contract for dynamic fees
    function setSBTContract(address _sbt) external onlyRole(ADMIN_ROLE) {
        sbtContract = ICreditScoreSBT(_sbt);
        emit SBTContractUpdated(_sbt);
    }

    /// @dev Get the effective fee for a buyer (SBT-adjusted or default)
    function getEffectiveFee(address buyer) public view returns (uint256) {
        if (address(sbtContract) != address(0)) {
            return sbtContract.getPlatformFee(buyer);
        }
        return platformFeePercent;
    }


    /**
     * @dev Deposit ERC20 tokens into escrow
     */
    function deposit(
        bytes32 orderId,
        address token,
        uint256 amount,
        address seller
    ) external nonReentrant whenNotPaused {
        require(orderId != bytes32(0), "Empty order ID");
        require(orders[orderId].buyer == address(0), "Order exists");
        require(seller != address(0), "Invalid seller");
        require(amount > 0, "Invalid amount");
        require(token != address(0), "Use depositNative for ETH/MATIC");
        
        uint256 feeBps = getEffectiveFee(msg.sender); // SBT-adjusted fee
        uint256 fee = (amount * feeBps) / 10000;
        uint256 sellerAmount = amount - fee;
        
        // Transfer tokens to escrow
        IERC20(token).safeTransferFrom(msg.sender, address(this), amount);
        
        orders[orderId] = Order({
            buyer: msg.sender,
            seller: seller,
            token: token,
            amount: sellerAmount,
            fee: fee,
            status: OrderStatus.Paid,
            createdAt: block.timestamp,
            expiresAt: block.timestamp + ORDER_TIMEOUT
        });
        
        emit OrderCreated(orderId, msg.sender, seller, token, sellerAmount, fee);
    }

    /**
     * @dev Deposit Native coins (ETH/MATIC/BNB) into escrow
     */
    function depositNative(
        bytes32 orderId,
        address seller
    ) external payable nonReentrant whenNotPaused {
        require(orderId != bytes32(0), "Empty order ID");
        require(orders[orderId].buyer == address(0), "Order exists");
        require(seller != address(0), "Invalid seller");
        require(msg.value > 0, "Invalid value");
        
        uint256 feeBps = getEffectiveFee(msg.sender);
        uint256 fee = (msg.value * feeBps) / 10000;
        uint256 sellerAmount = msg.value - fee;
        
        orders[orderId] = Order({
            buyer: msg.sender,
            seller: seller,
            token: address(0), // Marker for native token
            amount: sellerAmount,
            fee: fee,
            status: OrderStatus.Paid,
            createdAt: block.timestamp,
            expiresAt: block.timestamp + ORDER_TIMEOUT
        });
        
        emit OrderCreated(orderId, msg.sender, seller, address(0), sellerAmount, fee);
    }

    /**
     * @dev Deposit by swapping an input token to the required token natively
     */
    function depositWithSwap(
        bytes32 orderId,
        address inputToken,
        address requiredToken,
        uint256 amountIn,
        uint256 minAmountOut,
        address seller,
        address routerAddress
    ) external nonReentrant whenNotPaused {
        require(orderId != bytes32(0), "Empty order ID");
        require(orders[orderId].buyer == address(0), "Order exists");
        require(inputToken != address(0) && requiredToken != address(0), "ERC20 only");
        
        // Transfer inputToken to this contract
        IERC20(inputToken).safeTransferFrom(msg.sender, address(this), amountIn);
        
        // Approve router
        IERC20(inputToken).safeIncreaseAllowance(routerAddress, amountIn);
        
        // Setup path for DEX swap
        address[] memory path = new address[](2);
        path[0] = inputToken;
        path[1] = requiredToken;
        
        // Execute swap
        uint[] memory amounts = ISwapRouter(routerAddress).swapExactTokensForTokens(
            amountIn,
            minAmountOut,
            path,
            address(this),
            block.timestamp
        );
        
        uint256 receivedAmount = amounts[1];
        uint256 fee = (receivedAmount * platformFeePercent) / 10000;
        uint256 sellerAmount = receivedAmount - fee;
        
        // Store order as if they deposited the requiredToken directly
        orders[orderId] = Order({
            buyer: msg.sender,
            seller: seller,
            token: requiredToken,
            amount: sellerAmount,
            fee: fee,
            status: OrderStatus.Paid,
            createdAt: block.timestamp,
            expiresAt: block.timestamp + ORDER_TIMEOUT
        });
        
        emit OrderCreated(orderId, msg.sender, seller, requiredToken, sellerAmount, fee);
    }
    
    /**
     * @dev Release payment to seller (admin only)
     */
    function releasePayment(bytes32 orderId) 
        external 
        onlyRole(OPERATOR_ROLE) 
        nonReentrant 
    {
        Order storage order = orders[orderId];
        require(order.status == OrderStatus.Paid, "Invalid status");
        require(block.timestamp < order.expiresAt, "Order expired");
        
        order.status = OrderStatus.Completed;

        if (order.token == address(0)) {
            // Transfer Native
            (bool ok1, ) = order.seller.call{value: order.amount}("");
            require(ok1, "Seller transfer failed");
            (bool ok2, ) = feeVault.call{value: order.fee}("");
            require(ok2, "Fee transfer failed");
        } else {
            // Transfer ERC20
            IERC20(order.token).safeTransfer(order.seller, order.amount);
            IERC20(order.token).safeTransfer(feeVault, order.fee);
        }
        
        emit OrderCompleted(orderId);
    }
    
    /**
     * @dev Refund payment to buyer (admin only)
     */
    function refund(bytes32 orderId) 
        external 
        onlyRole(OPERATOR_ROLE) 
        nonReentrant 
    {
        Order storage order = orders[orderId];
        require(
            order.status == OrderStatus.Paid || 
            order.status == OrderStatus.Disputed, 
            "Invalid status"
        );
        
        order.status = OrderStatus.Refunded;
        uint256 totalRefund = order.amount + order.fee;

        if (order.token == address(0)) {
            (bool ok, ) = order.buyer.call{value: totalRefund}("");
            require(ok, "Refund transfer failed");
        } else {
            IERC20(order.token).safeTransfer(order.buyer, totalRefund);
        }
        
        emit OrderRefunded(orderId);
    }

    /**
     * @dev Auto-refund when order expires (anyone can call)
     */
    function refundExpired(bytes32 orderId) external nonReentrant {
        Order storage order = orders[orderId];
        require(order.status == OrderStatus.Paid, "Invalid status");
        require(block.timestamp >= order.expiresAt, "Not expired yet");

        order.status = OrderStatus.Expired;
        uint256 totalRefund = order.amount + order.fee;

        if (order.token == address(0)) {
            (bool ok, ) = order.buyer.call{value: totalRefund}("");
            require(ok, "Refund transfer failed");
        } else {
            IERC20(order.token).safeTransfer(order.buyer, totalRefund);
        }
        
        emit OrderExpired(orderId);
    }
    
    /**
     * @dev Mark order as disputed
     */
    function raiseDispute(bytes32 orderId) external {
        Order storage order = orders[orderId];
        require(
            msg.sender == order.buyer || msg.sender == order.seller,
            "Not authorized"
        );
        require(order.status == OrderStatus.Paid, "Invalid status");
        
        order.status = OrderStatus.Disputed;
        emit OrderDisputed(orderId);
    }
    
    /**
     * @dev Buyer confirms delivery and releases payment to seller directly.
     *      Emits DeliveryConfirmed - backend listens to update CreditScoreSBT.
     *      onTime = true if buyer confirms within 24h of order creation.
     */
    function buyerConfirmDelivery(bytes32 orderId) external nonReentrant {
        Order storage order = orders[orderId];
        require(msg.sender == order.buyer, "Not the buyer");
        require(order.status == OrderStatus.Paid, "Invalid status");
        require(block.timestamp < order.expiresAt, "Order expired");

        order.status = OrderStatus.Completed;

        if (order.token == address(0)) {
            (bool ok1, ) = order.seller.call{value: order.amount}("");
            require(ok1, "Seller transfer failed");
            (bool ok2, ) = feeVault.call{value: order.fee}("");
            require(ok2, "Fee transfer failed");
        } else {
            IERC20(order.token).safeTransfer(order.seller, order.amount);
            IERC20(order.token).safeTransfer(feeVault, order.fee);
        }

        // Determine if payment was on-time (within 24 hours of order creation)
        bool onTime = block.timestamp <= order.createdAt + 1 days;

        emit OrderCompleted(orderId);
        // Backend listens to DeliveryConfirmed to update CreditScoreSBT off-chain or via relayer
        emit DeliveryConfirmed(orderId, order.buyer, order.seller, onTime);
    }

    // Admin functions...

    function updatePlatformFee(uint256 newFeePercent) external onlyRole(ADMIN_ROLE) {
        require(newFeePercent <= MAX_FEE_PERCENT, "Fee too high");
        platformFeePercent = newFeePercent;
        emit FeeUpdated(newFeePercent);
    }
    
    function updateFeeVault(address newVault) external onlyRole(ADMIN_ROLE) {
        require(newVault != address(0), "Invalid vault");
        feeVault = newVault;
        emit FeeVaultUpdated(newVault);
    }
    
    function pause() external onlyRole(ADMIN_ROLE) { _pause(); }
    function unpause() external onlyRole(ADMIN_ROLE) { _unpause(); }
    
    function getOrder(bytes32 orderId) external view returns (Order memory) {
        return orders[orderId];
    }
}

contracts/ProductNFT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721URIStorage.sol";
import "@openzeppelin/contracts/token/common/ERC2981.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title ProductNFT
 * @dev ERC721 NFT for physical product authentication
 *      - ERC2981 royalty standard (OpenSea compatible)
 *      - Physical-Digital Link via NFC/QR hash
 *      - Multi-sig minting (2-of-3 admin approval)
 *      - Transferable to buyer on escrow release
 *
 * Each NFT represents ownership of a REAL physical product.
 * Metadata stored on IPFS to ensure immutability.
 */
contract ProductNFT is ERC721, ERC721URIStorage, ERC2981, AccessControl, Pausable, ReentrancyGuard {

    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");
    bytes32 public constant ADMIN_ROLE   = keccak256("ADMIN_ROLE");

    uint256 private _nextTokenId;

    // Platform default royalty (basis points, e.g. 500 = 5%)
    uint96 public constant DEFAULT_ROYALTY_BPS = 500; // 5%

    struct ProductMetadata {
        uint256 productId;        // DB product ID (off-chain reference)
        bytes32 physicalHash;     // keccak256 of NFC tag UID or QR serial - Physical-Digital Link
        address originalSeller;
        uint256 mintedAt;
        bool nfcVerified;         // true after buyer scans NFC/QR
    }

    // tokenId - metadata
    mapping(uint256 => ProductMetadata) public productMeta;

    // productId - tokenId (one product = one NFT)
    mapping(uint256 => uint256) public productToToken;

    // tokenId - pending transfer (set during escrow, released on delivery confirm)
    mapping(uint256 => address) public pendingBuyer;

    // Multi-sig: productId - approver set. Mint only after 2 approvals.
    mapping(uint256 => mapping(address => bool)) public mintApprovals;
    mapping(uint256 => uint8) public mintApprovalCount;
    mapping(uint256 => bytes) public pendingMintData; // ABI-encoded mint params

    uint8 public constant REQUIRED_APPROVALS = 2;

    // ------ Events ------
    event ProductMinted(uint256 indexed tokenId, uint256 indexed productId, address seller, string tokenURI);
    event NFCVerified(uint256 indexed tokenId, address buyer);
    event PendingTransferSet(uint256 indexed tokenId, address indexed buyer);
    event OwnershipTransferredOnDelivery(uint256 indexed tokenId, address from, address to);
    event MintApproved(uint256 indexed productId, address approver, uint8 count);
    event MintExecuted(uint256 indexed productId, uint256 tokenId);

    constructor(address feeVault) ERC721("Web3Market Product NFT", "W3MPNFT") {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
        _grantRole(MINTER_ROLE, msg.sender);

        // Set platform-wide default royalty - fee goes to feeVault
        _setDefaultRoyalty(feeVault, DEFAULT_ROYALTY_BPS);
    }

    // -----------------------------------------
    // MULTI-SIG MINT FLOW
    // -----------------------------------------

    /**
     * @dev Step 1: Admin proposes a mint. Stores encoded params.
     *      Second admin calls approveMint - auto-executes when count >= REQUIRED_APPROVALS.
     */
    function proposeMint(
        uint256 productId,
        string calldata tokenUri,
        bytes32 physicalHash,
        address seller,
        uint96 royaltyBps
    ) external onlyRole(ADMIN_ROLE) {
        require(productToToken[productId] == 0, "Already minted");
        mintApprovals[productId][msg.sender] = true;
        mintApprovalCount[productId] = 1;
        pendingMintData[productId] = abi.encode(productId, tokenUri, physicalHash, seller, royaltyBps);
        emit MintApproved(productId, msg.sender, 1);
    }

    /**
     * @dev Step 2: Second admin approves. If count reaches REQUIRED_APPROVALS, mint is executed.
     */
    function approveMint(uint256 productId) external onlyRole(ADMIN_ROLE) {
        require(!mintApprovals[productId][msg.sender], "Already approved");
        require(pendingMintData[productId].length > 0, "No pending mint");

        mintApprovals[productId][msg.sender] = true;
        mintApprovalCount[productId]++;
        emit MintApproved(productId, msg.sender, mintApprovalCount[productId]);

        if (mintApprovalCount[productId] >= REQUIRED_APPROVALS) {
            _executeMint(productId);
        }
    }

    function _executeMint(uint256 productId) internal {
        (
            uint256 pid,
            string memory tokenUri,
            bytes32 physicalHash,
            address seller,
            uint96 royaltyBps
        ) = abi.decode(pendingMintData[productId], (uint256, string, bytes32, address, uint96));

        uint256 tokenId = ++_nextTokenId;
        _safeMint(address(this), tokenId); // Contract holds NFT until buyer confirms delivery
        _setTokenURI(tokenId, tokenUri);
        if (royaltyBps > 0) {
            _setTokenRoyalty(tokenId, seller, royaltyBps);
        }

        productMeta[tokenId] = ProductMetadata({
            productId: pid,
            physicalHash: physicalHash,
            originalSeller: seller,
            mintedAt: block.timestamp,
            nfcVerified: false
        });
        productToToken[pid] = tokenId;

        // Clean up approval state
        delete pendingMintData[productId];
        delete mintApprovalCount[productId];

        emit ProductMinted(tokenId, pid, seller, tokenUri);
        emit MintExecuted(productId, tokenId);
    }

    // -----------------------------------------
    // DIRECT MINT (single admin / backend wallet - for non-multi-sig flow)
    // -----------------------------------------

    function mintProduct(
        uint256 productId,
        string calldata tokenUri,
        bytes32 physicalHash,
        address seller,
        uint96 royaltyBps
    ) external onlyRole(MINTER_ROLE) whenNotPaused nonReentrant {
        require(productToToken[productId] == 0, "Already minted");

        uint256 tokenId = ++_nextTokenId;
        _safeMint(address(this), tokenId); // held in contract escrow
        _setTokenURI(tokenId, tokenUri);
        if (royaltyBps > 0) {
            _setTokenRoyalty(tokenId, seller, royaltyBps);
        }

        productMeta[tokenId] = ProductMetadata({
            productId: productId,
            physicalHash: physicalHash,
            originalSeller: seller,
            mintedAt: block.timestamp,
            nfcVerified: false
        });
        productToToken[productId] = tokenId;

        emit ProductMinted(tokenId, productId, seller, tokenUri);
    }

    // -----------------------------------------
    // PHYSICAL-DIGITAL LINK - NFC / QR VERIFY
    // -----------------------------------------

    /**
     * @dev Buyer scans NFC tag / QR code on the physical product.
     *      The app hashes the scanned payload and calls this function.
     *      physicalHashInput must match the hash stored at minting.
     *      On success: sets nfcVerified = true and auto-transfers NFT to buyer.
     */
    function verifyAndClaim(
        uint256 tokenId,
        bytes32 physicalHashInput
    ) external nonReentrant {
        ProductMetadata storage meta = productMeta[tokenId];
        require(pendingBuyer[tokenId] == msg.sender, "Not the pending buyer");
        require(!meta.nfcVerified, "Already verified");
        require(meta.physicalHash == physicalHashInput, "Physical hash mismatch - not the authentic product");

        meta.nfcVerified = true;
        address prev = address(this);
        _transfer(prev, msg.sender, tokenId);
        delete pendingBuyer[tokenId];

        emit NFCVerified(tokenId, msg.sender);
        emit OwnershipTransferredOnDelivery(tokenId, prev, msg.sender);
    }

    // -----------------------------------------
    // ESCROW INTEGRATION
    // Called by EscrowCore (or backend) after delivery confirmation
    // -----------------------------------------

    /**
     * @dev Set pending buyer - called when order is placed + escrow funded.
     *      NFT will transfer to this address when buyer calls verifyAndClaim.
     */
    function setPendingBuyer(
        uint256 productId,
        address buyer
    ) external onlyRole(MINTER_ROLE) {
        uint256 tokenId = productToToken[productId];
        require(tokenId != 0, "NFT not minted yet");
        pendingBuyer[tokenId] = buyer;
        emit PendingTransferSet(tokenId, buyer);
    }

    /**
     * @dev Force transfer (no NFC required) - called when product does NOT have NFC tag.
     *      Used for standard products (non-luxury).
     */
    function deliverNFT(
        uint256 productId,
        address buyer
    ) external onlyRole(MINTER_ROLE) nonReentrant {
        uint256 tokenId = productToToken[productId];
        require(tokenId != 0, "NFT not minted");
        require(ownerOf(tokenId) == address(this), "Already delivered");
        _transfer(address(this), buyer, tokenId);
        delete pendingBuyer[tokenId];
        emit OwnershipTransferredOnDelivery(tokenId, address(this), buyer);
    }

    // -----------------------------------------
    // VIEWS
    // -----------------------------------------

    function getTokenByProduct(uint256 productId) external view returns (uint256) {
        return productToToken[productId];
    }

    function totalMinted() external view returns (uint256) {
        return _nextTokenId;
    }

    // -----------------------------------------
    // OVERRIDES (OpenZeppelin v5 requirements)
    // -----------------------------------------

    function tokenURI(uint256 tokenId)
        public view override(ERC721, ERC721URIStorage) returns (string memory)
    {
        return super.tokenURI(tokenId);
    }

    function supportsInterface(bytes4 interfaceId)
        public view override(ERC721, ERC721URIStorage, ERC2981, AccessControl) returns (bool)
    {
        return super.supportsInterface(interfaceId);
    }

    function pause() external onlyRole(ADMIN_ROLE) { _pause(); }
    function unpause() external onlyRole(ADMIN_ROLE) { _unpause(); }
}

